-- Write your PostgreSQL query statement below
SELECT p.product_id,COALESCE(ROUND((SUM( p.price ::numeric * u.units) / NULLIF(SUM(u.units),0)),2),0 )AS average_price FROM prices p left JOIN unitssold u ON p.product_id = u.product_id AND p.start_date <= u.purchase_date AND p.end_date >= u.purchase_date GROUP BY p.product_id